import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_dim1_f32(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 dim1,
    .param .s32 dim2
)
{
    .reg .pred %p1, %p2;
    .reg .u32 %r1, %r2, %r3, %r4, %r5, %r6, %r7, %r8;
    .reg .u64 %rd1, %rd2, %rd3, %rd4, %rd5, %rd6, %rd7, %rd8, %rd9, %rd10, %rd11, %rd12, %rd13, %rd14, %rd15;
    .reg .f32 %f1, %f2;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.s32 %r7, [dim1];
    ld.param.s32 %r8, [dim2];

    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ctaid.y;
    mov.u32 %r4, %ntid.x;
    mad.lo.s32 %r5, %r2, %r4, %r1;

    setp.ge.s32 %p1, %r5, %r8;
    @%p1 ret;

    cvt.u64.u32 %rd3, %r3;
    cvt.u64.u32 %rd4, %r7;
    cvt.u64.u32 %rd5, %r8;
    mul.lo.u64 %rd6, %rd4, %rd5;
    mul.lo.u64 %rd7, %rd3, %rd6;
    cvt.u64.u32 %rd8, %r5;
    add.u64 %rd9, %rd7, %rd8;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd1, %rd10;

    shl.b64 %rd13, %rd5, 2;

    mul.lo.u64 %rd14, %rd3, %rd5;
    add.u64 %rd14, %rd14, %rd8;
    shl.b64 %rd14, %rd14, 2;
    add.u64 %rd15, %rd2, %rd14;

    ld.global.f32 %f1, [%rd11];
    mov.u32 %r6, 1;

$L_loop:
    setp.lt.s32 %p2, %r6, %r7;
    @!%p2 bra $L_done;
    add.u64 %rd11, %rd11, %rd13;
    ld.global.f32 %f2, [%rd11];
    max.f32 %f1, %f1, %f2;
    add.s32 %r6, %r6, 1;
    bra $L_loop;

$L_done:
    st.global.f32 [%rd15], %f1;
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("max_reduce_dim1_f32")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, dim1, dim2 = x.shape
        out = torch.empty((batch_size, dim2), device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        module.launch(
            "max_reduce_dim1_f32",
            grid=((dim2 + 255) // 256, batch_size, 1),
            block=(256, 1, 1),
            arguments=[x, out, i32(dim1), i32(dim2)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

